"""🪦 [isov] batch `retire`: the private repository retires a partition even when a test left nested volumes mounted below it (a namespace image whose owner is gone: the deadline law, a killed test process reaped later); the clear step detaches such volumes, deepest first, before it removes the directory. Re-run = rebase onto the current live bytes (exit 2 names a lost anchor)."""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from mkbatch import build, live_bytes, replace_once
REL = "🧰️framework/🛍️products/🦑️repo/🔨️modules/📚️library/🧪️testing/🧫️private-repository/🟦️.ts"
base = live_bytes(REL); text = base.decode("utf-8")
text = replace_once(text, 'import {existsSync,readFileSync,realpathSync,writeFileSync} from "node:fs";', 'import {spawnSync} from "node:child_process";\nimport {existsSync,lstatSync,readdirSync as readdirSyncV1,readFileSync,realpathSync,writeFileSync} from "node:fs";', "fs import")
text = replace_once(text, '/** 🪦️ Retires one private partition image with the genuine protocol', '/** 🔌️ Detaches the volumes a test left mounted below one path, deepest first: their owner is gone, so no genuine protocol can retire them, and a mounted volume refuses its own removal. */\nfunction detachNestedVolumesV1(path:string,parentDevice:number):void{\n let stat;try{stat=lstatSync(path);}catch{return;}\n if(!stat.isDirectory())return;\n for(const name of readdirSyncV1(path))detachNestedVolumesV1(join(path,name),stat.dev);\n if(stat.dev!==parentDevice&&process.platform==="darwin")spawnSync("hdiutil",["detach",path,"-force"],{stdio:"ignore"});\n}\n/** 🪦️ Retires one private partition image with the genuine protocol', "function anchor")
text = replace_once(text, 'continue;await rm(requireNativeStoragePathV1(image.root,join(image.root,name)),{recursive:true,force:true});}', 'continue;detachNestedVolumesV1(join(image.root,name),lstatSync(image.root).dev);await rm(requireNativeStoragePathV1(image.root,join(image.root,name)),{recursive:true,force:true});}', "clear step")
text = replace_once(text, 'let cleared=false;\n  const retiring=nativeStorageRetirementPortV1(port,async()=>{if(cleared)return;', 'let cleared=false,pending=state.allocations.length;\n  const retiring=nativeStorageRetirementPortV1(port,async()=>{if(cleared||--pending>0)return;', "last allocation clears")
text = replace_once(text, 'async function retirePrivatePartitionV1(options:any):Promise<void>{\n const image=await', 'async function retirePrivatePartitionV1(options:any):Promise<void>{\n const mounted=join(options.directory,"m");if(existsSync(mounted)){const device=lstatSync(mounted).dev;for(const name of readdirSyncV1(mounted))detachNestedVolumesV1(join(mounted,name),device);}\n const image=await', "pre-open detach")
build("retire", "🪦 Staged batch `retire` (lane isov): the private repository retires partitions that hold nested volumes a test left mounted.", {REL: (base, text.encode("utf-8"))}, {})
